import{_ as a,a as t,c as s,ac as d}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Linux 常用命令：用途、参数与操作边界 · ps 列出当前系统进程至Linux 常用命令","description":"把基础解释与按使用流程排列的命令表集中为一个速查入口。","frontmatter":{"title":"Linux 常用命令：用途、参数与操作边界 · ps 列出当前系统进程至Linux 常用命令","description":"把基础解释与按使用流程排列的命令表集中为一个速查入口。","splitFrom":"systems/linux/common-commands.md","showdocs":{"topics":[{"id":"linux","title":"Linux","link":"/topics/linux/"},{"id":"network","title":"网络配置与诊断","link":"/topics/network/"}],"kind":"命令与系统观察","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"Linux 常用命令：用途、参数与操作边界","summary":"把基础解释与按使用流程排列的命令表集中为一个速查入口。","status":"active","related":[{"title":"Linux 常用命令：用途、参数与操作边界","link":"/systems/linux/common-commands","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 按发行版选择包管理器至备份与同步","link":"/systems/linux/common-commands-part-06","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 浏览、创建与移动文件至文本筛选、统计与比较","link":"/systems/linux/common-commands-part-04","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 维护与旧设备场景","link":"/systems/linux/common-commands-part-07","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 账号、权限与属性至磁盘容量与挂载","link":"/systems/linux/common-commands-part-05","kind":"命令与系统观察","scope":"general","audience":"general"}],"prev":{"text":"Linux 常用命令：用途、参数与操作边界 · touch 创建新文件至top 实时显示进程状态","link":"/systems/linux/common-commands-part-02"},"next":{"text":"Linux 常用命令：用途、参数与操作边界 · 浏览、创建与移动文件至文本筛选、统计与比较","link":"/systems/linux/common-commands-part-04"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Linux 常用命令：用途、参数与操作边界 · touch 创建新文件至top 实时显示进程状态","link":"/systems/linux/common-commands-part-02"},"next":{"text":"Linux 常用命令：用途、参数与操作边界 · 浏览、创建与移动文件至文本筛选、统计与比较","link":"/systems/linux/common-commands-part-04"}},"headers":[],"relativePath":"systems/linux/common-commands-part-03.md","filePath":"systems/linux/common-commands-part-03.md"}'),i={name:"systems/linux/common-commands-part-03.md"};function o(c,e,n,p,l,r){return t(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="linux-常用命令-用途、参数与操作边界-·-ps-列出当前系统进程至linux-常用命令" tabindex="-1">Linux 常用命令：用途、参数与操作边界 · ps 列出当前系统进程至Linux 常用命令 <a class="header-anchor" href="#linux-常用命令-用途、参数与操作边界-·-ps-列出当前系统进程至linux-常用命令" aria-label="Permalink to &quot;Linux 常用命令：用途、参数与操作边界 · ps 列出当前系统进程至Linux 常用命令&quot;">​</a></h1><p><a href="/systems/linux/common-commands">返回分篇目录</a></p><p>先按任务进入主速查；需要理解参数时再展开后面的逐条解释。命令未执行，平台与权限按相应条目核对。</p><h2 id="part-1-ps-列出当前系统进程" tabindex="-1">ps 列出当前系统进程 <a class="header-anchor" href="#part-1-ps-列出当前系统进程" aria-label="Permalink to &quot;ps 列出当前系统进程 {#part-1-ps-列出当前系统进程}&quot;">​</a></h2><p><code>ps</code> 命令用于列出当前系统中运行的进程信息，可以查看进程 ID、进程名称、占用 CPU 时间、内存等资源的情况，并且可以按照不同的指标进行排序。</p><p>以下是 <code>ps</code> 命令的基本语法：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ps [options]</span></span></code></pre></div><p>默认情况下，<code>ps</code> 命令只会显示当前用户自己运行的进程信息。如果需要查看所有进程的信息，需要使用 <code>-e</code> 或者 <code>-A</code> 选项。例如，以下命令将列出当前系统中所有进程的信息并按照进程 ID 排序：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ps -eo pid,ppid,cmd,%cpu,%mem --sort=-pid</span></span></code></pre></div><p>其中，<code>-e</code> 选项表示要显示所有进程的信息，<code>-o</code> 选项指定要显示的字段，<code>--sort</code> 选项指定排序方式。上述命令将显示 PID、父进程 ID、进程名、CPU 使用率、内存使用率等信息，并按照进程 ID 从大到小进行排序。</p><p>下面是一些常用的选项：</p><ul><li><code>-e</code>: 显示所有进程的信息。</li><li><code>-A</code>: 显示所有进程的信息，与 <code>-e</code> 选项类似。</li><li><code>-f</code>: 显示完整的进程信息，包括进程的 UID、GID、PPID 等。</li><li><code>-u username</code>: 显示指定用户的进程信息。</li><li><code>-p pidlist</code>: 显示指定 PID 列表对应的进程信息。</li></ul><p>例如，以下命令将显示当前用户运行的所有进程：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ps -u $USER</span></span></code></pre></div><p>如果想要查看某个进程的详细信息，可以使用 <code>-f</code> 选项：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ps -ef | grep nginx</span></span></code></pre></div><p>以上是 <code>ps</code> 命令的一些基本用法和选项。需要注意的是，在不同的操作系统中，<code>ps</code> 命令的参数和输出格式可能有所不同。</p><h2 id="part-1-kill-结束某个进程" tabindex="-1">kill 结束某个进程 <a class="header-anchor" href="#part-1-kill-结束某个进程" aria-label="Permalink to &quot;kill 结束某个进程 {#part-1-kill-结束某个进程}&quot;">​</a></h2><p><code>kill</code> 命令用于终止指定进程或者发送信号给指定进程。可以使用 <code>ps</code> 命令查找要终止的进程的 PID，然后使用 <code>kill</code> 命令向该进程发送终止信号。</p><p>以下是 <code>kill</code> 命令的基本语法：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kill [options] pid ...</span></span></code></pre></div><p>其中，<code>pid</code> 表示要终止的进程的 PID。多个 PID 可以用空格分隔。如果在命令行中不指定任何选项，则默认向进程发送 SIGTERM 信号，让其正常退出。</p><p>下面是一些常用的选项：</p><ul><li><code>-l</code>: 列出所有可用的信号名称。</li><li><code>-9</code>: 强制终止进程，使用 SIGKILL 信号。</li><li><code>-s signal</code>: 指定要发送的信号类型（使用信号名称或数字）。</li></ul><p>例如，以下命令将向进程编号为 12345 发送 SIGTERM 信号，让其正常退出：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kill 12345</span></span></code></pre></div><p>如果想要强制终止某个进程，可以使用 <code>-9</code> 选项：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kill -9 12345</span></span></code></pre></div><p>如果想要发送其他类型的信号，可以使用 <code>-s</code> 选项，如向进程 12345 发送 SIGUSR1 信号：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kill -s SIGUSR1 12345</span></span></code></pre></div><p>以上是 <code>kill</code> 命令的一些基本用法和选项。需要注意的是，强制终止进程可能会导致数据丢失或者出现其他问题，应该尽量避免使用 <code>-9</code> 选项。</p><h2 id="part-1-tar-打包或解压缩文件" tabindex="-1">tar 打包或解压缩文件 <a class="header-anchor" href="#part-1-tar-打包或解压缩文件" aria-label="Permalink to &quot;tar 打包或解压缩文件 {#part-1-tar-打包或解压缩文件}&quot;">​</a></h2><p><code>tar</code>(tape archive)命令用于在 Linux 中创建和解压归档文件，可以将多个文件或目录打包成一个文件，并且可以使用不同的压缩算法进行压缩。 <code>tar</code> 命令经常用于备份数据以及在多台服务器之间传输文件。</p><p>以下是 <code>tar</code> 命令的基本语法：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tar [options] [archive_name] [files/dirs]</span></span></code></pre></div><p>其中，<code>archive_name</code> 表示要创建的归档文件的名称，<code>files/dirs</code> 则表示要添加到归档文件中的文件或目录列表。如果没有指定归档文件名称，则默认会将归档文件输出到标准输出。如果同时指定了归档文件名称和文件列表，则 <code>tar</code> 命令将把这些文件添加到归档文件中。</p><p>下面是一些常用的选项：</p><ul><li><code>-c</code>: 创建新的归档文件。</li><li><code>-x</code>: 从归档文件中提取文件。</li><li><code>-v</code>: 显示详细信息，包括要添加或提取的文件列表。</li><li><code>-f file</code>: 指定归档文件的名称。</li><li><code>-z</code>: 对归档文件进行 gzip 压缩。</li><li><code>-j</code>: 对归档文件进行 bzip2 压缩。</li><li><code>-C dir</code>: 指定要操作的目录。</li></ul><p>例如，以下命令将创建名为 <code>myarchive.tar</code> 的归档文件，并将目录 <code>mydir</code> 中的所有文件添加到该归档文件中：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tar -cvf myarchive.tar mydir/</span></span></code></pre></div><p>如果想要将归档文件解压到当前目录下，可以使用以下命令：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tar -xvf myarchive.tar</span></span></code></pre></div><p>如果想要将归档文件进行 bzip2 压缩，并且指定要操作的目录为 <code>/home</code>，可以使用以下命令：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tar -cjvf home.tar.bz2 -C / home/</span></span></code></pre></div><p>以上是 <code>tar</code> 命令的一些基本用法和选项。需要注意的是，在不同的操作系统中，<code>tar</code> 命令的参数和输出格式可能有所不同。</p><h2 id="part-1-vim" tabindex="-1">vim <a class="header-anchor" href="#part-1-vim" aria-label="Permalink to &quot;vim {#part-1-vim}&quot;">​</a></h2><p><code>Vim</code>(Vi IMproved) 是一个高级的文本编辑器，是 Unix 和类 Unix 系统中最受欢迎的编辑器之一。它可以处理多种文件类型，包括纯文本、代码等，并且支持多种操作模式和自定义配置，可以提高编辑效率。</p><p>以下是 <code>Vim</code> 的一些基本概念和使用方法：</p><ol><li>操作模式：<code>Vim</code> 有三种操作模式，分别是命令模式（Command mode）、插入模式（Insert mode）和视觉模式（Visual mode）。命令模式用于执行命令、移动光标等操作；插入模式用于输入文本；视觉模式用于选择文本。</li><li>命令：在命令模式下，可以使用各种命令进行操作，如移动光标、删除文本、复制粘贴等。常用命令包括 h/j/k/l 分别表示左/下/上/右方向键；i/a/o 分别表示插入、在光标后插入、在行尾插入；dd 表示删除整行；yy 表示复制整行；p 表示将复制的内容粘贴到当前位置。</li><li>配置文件：<code>Vim</code> 使用 <code>.vimrc</code> 文件来存储用户自定义设置和插件配置。可以通过修改该文件来实现自定义配置，如设置显示行号、设置缩进等。</li><li>插件：<code>Vim</code> 支持多种插件，可以通过安装插件来扩展其功能。一些常用的插件包括 NERDTree（文件浏览器）、vim-airline（状态栏增强）、YouCompleteMe（自动补全）等。</li></ol><p>以下是 <code>Vim</code> 的一些使用方法：</p><ol><li>打开文件：使用 <code>vim</code> 命令加上要打开的文件名称即可打开，如 <code>vim test.txt</code>。</li><li>切换模式：在命令模式下按下 i/a/o 进入插入模式，在插入模式下按下 Esc 进入命令模式，在命令模式下按下 v 进入视觉模式。</li><li>保存文件：在命令模式下按下 :w 即可保存文件，若要保存并退出可以按下 :wq。</li><li>查找和替换：在命令模式下按下 / 进入查找模式，输入要查找的内容后按下 Enter；在命令模式下按下 😒/old/new/g 进行替换，其中 old 表示要被替换的文本，new 表示替换成的文本，g 表示全局匹配。</li><li>多窗口操作：在命令模式下按下 :sp 可以在当前窗口中水平分割一个新窗口，按下 :vsp 可以在当前窗口中垂直分割一个新窗口，使用 Ctrl+w 进行窗口切换。</li></ol><p>以上是 <code>Vim</code> 的一些基本概念和使用方法。需要注意的是，由于 <code>Vim</code> 具有较高的学习曲线，初学者可能需要花费一些时间来适应其操作方式。</p><h2 id="part-2" tabindex="-1">Linux 常用命令 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;Linux 常用命令 {#part-2}&quot;">​</a></h2><blockquote><p>以下保留原资料的历史版本范围。</p></blockquote><p>按使用流程查找：先<a href="/systems/linux/common-commands-part-03#part-2-识别系统与设备">识别系统</a>，再<a href="/systems/linux/common-commands-part-04#part-2-浏览、创建与移动文件">浏览和操作文件</a>、<a href="/systems/linux/common-commands-part-04#part-2-搜索文件与命令">搜索</a>、<a href="/systems/linux/common-commands-part-04#part-2-读取文件与日志">查看与处理文本</a>、<a href="/systems/linux/common-commands-part-05#part-2-账号、权限与属性">权限</a>、<a href="/systems/linux/common-commands-part-05#part-2-打包与压缩">归档</a>、<a href="/systems/linux/common-commands-part-05#part-2-磁盘容量与挂载">磁盘</a>、<a href="/systems/linux/common-commands-part-06#part-2-按发行版选择包管理器">包管理</a>和<a href="/systems/linux/common-commands-part-06#part-2-备份与同步">传输备份</a>。需要性能或故障调查时进入 <a href="/systems/linux/base/advanced/advanced">Linux 进阶排障</a>。</p><p>这些是多发行版历史速查，命令是否安装、参数和设备名以目标系统为准。文件修改前核对目标；格式化、关机和旧设备操作集中放在最后的<a href="/systems/linux/common-commands-part-07#part-2-维护与旧设备场景">维护操作</a>，不要按整表依次执行。</p><h3 id="part-2-识别系统与设备" tabindex="-1">识别系统与设备 <a class="header-anchor" href="#part-2-识别系统与设备" aria-label="Permalink to &quot;识别系统与设备 {#part-2-识别系统与设备}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途与边界</th></tr></thead><tbody><tr><td><code>arch</code></td><td>显示机器的处理器架构</td></tr><tr><td><code>uname -m</code></td><td>显示机器的处理器架构</td></tr><tr><td><code>uname -r</code></td><td>显示正在使用的内核版本</td></tr><tr><td><code>dmidecode -q</code></td><td>显示硬件系统部件 - (SMBIOS / DMI)</td></tr><tr><td><code>hdparm -i /dev/hda</code></td><td>罗列一个磁盘的架构特性</td></tr><tr><td><code>hdparm -tT /dev/sda</code></td><td>在磁盘上执行测试性读取操作</td></tr><tr><td><code>cat /proc/cpuinfo</code></td><td>显示CPU的信息</td></tr><tr><td><code>cat /proc/interrupts</code></td><td>显示中断</td></tr><tr><td><code>cat /proc/meminfo</code></td><td>查看内存统计</td></tr><tr><td><code>cat /proc/swaps</code></td><td>显示哪些swap被使用</td></tr><tr><td><code>cat /proc/version</code></td><td>显示内核的版本</td></tr><tr><td><code>cat /proc/net/dev</code></td><td>显示网络适配器及统计信息</td></tr><tr><td><code>cat /proc/mounts</code></td><td>显示已加载的文件系统</td></tr><tr><td><code>lspci -tv</code></td><td>罗列出所有的 PCI 设备</td></tr><tr><td><code>lsusb -tv</code></td><td>显示 USB 设备</td></tr><tr><td><code>date</code></td><td>显示系统日期</td></tr><tr><td><code>cal 2020</code></td><td>显示2020年的日历表</td></tr></tbody></table>',58)])])}const h=a(i,[["render",o]]);export{u as __pageData,h as default};
